const money = paise => new Intl.NumberFormat("en-IN", { style:"currency", currency:"INR", maximumFractionDigits:2 }).format(Number(paise || 0) / 100);
const dateText = value => value ? new Date(Number(value)).toLocaleString("en-IN", { dateStyle:"medium", timeStyle:"short" }) : "—";
const upiLink = (upiId, name, paise, note) => "upi://pay?" + new URLSearchParams({ pa:upiId, pn:name, am:(Number(paise)/100).toFixed(2), cu:"INR", tn:note || "OneUPay payment" }).toString();
const shareLink = id => window.location.origin + "/pay/" + encodeURIComponent(id);
const safeCsv = value => '"' + String(value ?? "").replace(/"/g,'""').replace(/^[=+\-@]/,"'$&") + '"';
const copyText = async value => { try { await navigator.clipboard.writeText(value); return true; } catch { window.prompt("Copy this value", value); return false; } };
function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
}
function printReceipt(link, claim) {
  const title = escapeHtml(link.merchantName || "Merchant");
  const description = escapeHtml(link.description || "Payment");
  const payer = escapeHtml(claim?.payerName || "Payer");
  const utr = escapeHtml(claim?.utr || "Not recorded");
  const id = escapeHtml(link.id);
  const amount = escapeHtml(money(link.amountPaise));
  const when = escapeHtml(dateText(link.verifiedAt));
  const html = `<!doctype html><html><head><meta charset="utf-8"><title>OneUPay receipt</title><style>body{font:15px Arial,sans-serif;color:#142338;padding:28px;max-width:650px;margin:auto}.card{border:1px solid #dce8e6;border-radius:16px;padding:25px}.brand{color:#079e88;font-weight:bold;font-size:22px}.stamp{background:#e7f8f1;color:#087d63;padding:10px;border-radius:8px;margin:20px 0}.amount{font-size:32px;font-weight:bold;margin:14px 0}.row{display:flex;justify-content:space-between;gap:14px;padding:10px 0;border-bottom:1px solid #edf1f3}.muted{color:#758594;font-size:11px;line-height:1.6}@media print{button{display:none}}</style></head><body><div class="card"><div class="brand">OneUPay</div><p class="muted">Merchant-generated payment receipt · Preview</p><div class="stamp">MANUALLY VERIFIED BY MERCHANT</div><h2>Payment receipt</h2><div class="amount">${amount}</div><div class="row"><span>Merchant</span><b>${title}</b></div><div class="row"><span>Description</span><b>${description}</b></div><div class="row"><span>Payer</span><b>${payer}</b></div><div class="row"><span>UPI reference</span><b>${utr}</b></div><div class="row"><span>Verified at</span><b>${when}</b></div><div class="row"><span>Link ID</span><b>${id}</b></div><p class="muted">This receipt records the merchant's manual status update. It is not a bank-issued receipt, payment-provider confirmation, or proof of irreversible settlement.</p><button onclick="window.print()">Print / Save as PDF</button></div><script>setTimeout(()=>window.print(),350)</script></body></html>`
  const win = window.open("", "_blank");
  if (!win) { window.alert("Allow pop-ups to print this receipt."); return; }
  win.document.open(); win.document.write(html); win.document.close();
}
function downloadQr() {
  const svg = document.querySelector("#checkout-qr-image svg");
  if (!svg) return;
  const copy = svg.cloneNode(true);
  copy.setAttribute("xmlns", "http://www.w3.org/2000/svg");
  const blob = new Blob([new XMLSerializer().serializeToString(copy)], {type:"image/svg+xml"});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href=url; a.download="oneupay-payment-qr.svg"; a.click();
  URL.revokeObjectURL(url);
}
